<script setup lang="ts">import Table from './common/Table.vue';import Status from './common/Status.vue';import {fmt,groupingOf} from '../utils/format';defineProps<{runs:any[]}>();defineEmits(['open']);function unit(r:any){if(!r.result)return r.status==='failed'?'失败':'等待核算';const g=groupingOf(r.result);return g.resampling_unit==='core_cluster'?`整芯${g.core_count}组/${g.specimen_count}试样`:'逐试样'}</script><template><Table :headers="['研究运行','状态','重采样单位','重复/seed','κ','打开']"><tr v-for="r in runs" :key="r.id"><td><strong>{{r.name}}</strong><small>#{{r.id}} / 研究{{r.study_id}}</small></td><td><Status :value="r.status"/><small v-if="r.error" class="error-text">{{r.error}}</small></td><td>{{unit(r)}}<small v-if="groupingOf(r.result).unequal_group_sizes">组大小不等</small></td><td>{{r.config.bootstrap_repeats}} / {{r.config.seed}}</td><td>{{r.kappa===null?'—':fmt(r.kappa,6)}}</td><td><button @click="$emit('open',r)">查看评议 ↗</button></td></tr></Table></template>
